// ── Sub-componentes (sin hooks problemáticos) ──
function Toggle({on,onToggle,ac="#2563EB"}){
  return(
    <div onClick={onToggle} style={{width:44,height:24,borderRadius:12,background:on?ac:"#CBD5E1",cursor:"pointer",position:"relative",transition:"background .2s",flexShrink:0}}>
      <div style={{position:"absolute",top:2,left:on?22:2,width:20,height:20,borderRadius:"50%",background:"#fff",transition:"left .2s",boxShadow:"0 1px 4px rgba(0,0,0,.2)"}}/>
    </div>
  );
}

function VideoPlayer({vid,onBack}){
  const [t,setT]=useState(0);
  const total=parseInt(vid.dur)*60;
  useEffect(()=>{const i=setInterval(()=>setT(p=>p<total?p+1:p),1000);return()=>clearInterval(i);},[total]);
  const fmt=s=>`${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`;
  return(
    <div style={{position:"absolute",top:0,left:0,right:0,bottom:0,background:"#000",display:"flex",flexDirection:"column",zIndex:200}}>
      <div style={{background:"#1E293B",aspectRatio:"16/9",display:"flex",alignItems:"center",justifyContent:"center",fontSize:64}}>{vid.e}</div>
      <div style={{padding:16,flex:1}}>
        <h2 style={{fontSize:16,fontWeight:800,color:"#fff",marginBottom:6}}>{vid.t}</h2>
        <p style={{fontSize:12,color:"#94A3B8",marginBottom:14}}>{vid.d}</p>
        <div style={{background:"#334155",borderRadius:4,height:4,marginBottom:8}}>
          <div style={{height:4,borderRadius:4,background:"#2563EB",width:`${(t/total)*100}%`,transition:"width 1s"}}/>
        </div>
        <div style={{display:"flex",justifyContent:"space-between",marginBottom:16}}>
          <span style={{fontSize:11,color:"#94A3B8"}}>{fmt(t)}</span>
          <span style={{fontSize:11,color:"#94A3B8"}}>{vid.dur}</span>
        </div>
        <button onClick={onBack} style={{background:"#2563EB",color:"#fff",border:"none",borderRadius:10,padding:"12px",fontSize:13,fontWeight:700,cursor:"pointer",width:"100%"}}>← Volver</button>
      </div>
    </div>
  );
}

