    btnG:{background:"transparent",color:D.blue,border:`2px solid ${D.blue}`,borderRadius:12,padding:EM?"14px 14px":"10px 14px",fontSize:EM?17:13,fontWeight:700,cursor:"pointer",width:"100%"},
    btnSm:{padding:EM?"8px 14px":"5px 12px",fontSize:EM?14:11,fontWeight:700,borderRadius:8,border:"none",cursor:"pointer"},
