    inpEl:{border:"none",background:"transparent",fontSize:EM?18:13,outline:"none",flex:1,color:Dc.t,fontFamily:"inherit",fontWeight:EM?600:400},
    row:{display:"flex",alignItems:"center",gap:10,padding:EM?18:12,background:Dc.card,borderRadius:14,border:`${EM?2:1}px solid ${Dc.border}`,marginBottom:EM?14:8,cursor:"pointer"},
    scr:{flex:1,overflowY:"auto",padding:EM?22:16,background:Dc.bg},
