                          <span style={{fontSize:10,color:m.stock<=STOCK_CRITICO?D.red:D.t2,fontWeight:m.stock<=STOCK_CRITICO?700:400}}>📦 {m.stock<=STOCK_CRITICO?"⚠ ":""}{m.stock} unidades</span>
